"use client";

import { useEffect, useState } from "react";
import type { Transition } from "motion/react";
import { useHydratedReducedMotion } from "@/lib/use-reduced-motion";
import { cn } from "@/lib/utils";

export { cn, useHydratedReducedMotion };

export type MomentProps = {
  className?: string;
  preview?: boolean;
};

export const springFast: Transition = { type: "spring", stiffness: 620, damping: 32 };
export const springSoft: Transition = { type: "spring", stiffness: 260, damping: 22 };
export const springBounce: Transition = { type: "spring", stiffness: 380, damping: 18 };
export const springHeavy: Transition = { type: "spring", stiffness: 200, damping: 26 };
export const springSnap: Transition = { type: "spring", stiffness: 700, damping: 38 };

export const tweenFast: Transition = { duration: 0.18, ease: [0.23, 1, 0.32, 1] };
export const tweenSoft: Transition = { duration: 0.32, ease: [0.23, 1, 0.32, 1] };

export const surface =
  "relative flex h-[150px] w-[230px] max-w-full select-none items-center justify-center text-foreground";

export function usePreviewPulse(
  preview: boolean | undefined,
  duration = 900,
  gap = 2500,
) {
  const [on, setOn] = useState(false);
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) {
      setOn(false);
      return;
    }
    let close = 0;
    let next = 0;
    const run = () => {
      setOn(true);
      close = window.setTimeout(() => setOn(false), duration);
      next = window.setTimeout(run, gap);
    };
    run();
    return () => {
      window.clearTimeout(close);
      window.clearTimeout(next);
    };
  }, [preview, reduce, duration, gap]);

  return on && !reduce;
}

export function usePreviewStep(
  preview: boolean | undefined,
  steps: number,
  interval = 1500,
) {
  const [step, setStep] = useState(0);
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) return;
    setStep(1);
    const id = window.setInterval(
      () => setStep((current) => (current + 1) % steps),
      interval,
    );
    return () => window.clearInterval(id);
  }, [preview, reduce, steps, interval]);

  return reduce ? 0 : step;
}

export function usePreviewPointer(
  preview: boolean | undefined,
  width = 220,
  height = 120,
) {
  const [point, setPoint] = useState({ x: width / 2, y: height / 2 });
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) return;
    let frame = 0;
    let start = 0;
    const loop = (time: number) => {
      if (!start) start = time;
      const t = (time - start) / 1000;
      const x = width / 2 + Math.cos(t * 1.4) * (width * 0.36);
      const y = height / 2 + Math.sin(t * 2.1) * (height * 0.28);
      setPoint({ x, y });
      frame = requestAnimationFrame(loop);
    };
    frame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frame);
  }, [preview, reduce, width, height]);

  return [point, setPoint] as const;
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

/**
 * The docs stage zooms its children (CSS `zoom`), so a pointer event reports
 * positions in zoomed pixels while the component lays itself out unscaled.
 * Normalise the event back into the component's own coordinate space.
 */
export function localPoint(
  event: { clientX: number; clientY: number },
  node: HTMLElement,
) {
  const rect = node.getBoundingClientRect();
  const scaleX = node.offsetWidth ? rect.width / node.offsetWidth : 1;
  const scaleY = node.offsetHeight ? rect.height / node.offsetHeight : 1;
  return {
    x: (event.clientX - rect.left) / (scaleX || 1),
    y: (event.clientY - rect.top) / (scaleY || 1),
  };
}

export function naturalWidth(node: HTMLElement) {
  return node.offsetWidth || node.getBoundingClientRect().width;
}

export function pointerScaleX(node: HTMLElement) {
  const rect = node.getBoundingClientRect();
  return node.offsetWidth ? rect.width / node.offsetWidth : 1;
}

"use client";

import { motion } from "motion/react";
import { Copy, EyeOff, Move, Pencil, Share2, Tag } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import {
  cn,
  springBounce,
  surface,
  useHydratedReducedMotion,
  usePreviewPulse,
  type MomentProps,
} from "./shared";

const ITEMS = [
  { label: "Edit", angle: -90, Icon: Pencil },
  { label: "Copy", angle: -30, Icon: Copy },
  { label: "Share", angle: 30, Icon: Share2 },
  { label: "Tag", angle: 90, Icon: Tag },
  { label: "Move", angle: 150, Icon: Move },
  { label: "Hide", angle: 210, Icon: EyeOff },
];
const RADIUS = 48;

export function RadialMenu({ className, preview }: MomentProps) {
  const [open, setOpen] = useState(false);
  const [chosen, setChosen] = useState<string | null>(null);
  const reduce = useHydratedReducedMotion();
  const pulse = usePreviewPulse(preview, 1400, 3000);
  const shown = preview ? pulse : open;
  const trigger = useRef<HTMLButtonElement | null>(null);
  const items = useRef<(HTMLButtonElement | null)[]>([]);

  useEffect(() => {
    if (open) items.current[0]?.focus();
  }, [open]);

  const close = (returnFocus: boolean) => {
    setOpen(false);
    if (returnFocus) trigger.current?.focus();
  };

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (!open) return;
    if (event.key === "Escape") {
      event.preventDefault();
      close(true);
      return;
    }
    const forward = event.key === "ArrowRight" || event.key === "ArrowDown";
    const backward = event.key === "ArrowLeft" || event.key === "ArrowUp";
    if (!forward && !backward) return;
    event.preventDefault();
    const current = items.current.findIndex((node) => node === document.activeElement);
    const next =
      (current + (forward ? 1 : -1) + ITEMS.length) % ITEMS.length;
    items.current[next]?.focus();
  };

  return (
    <div className={cn(surface, "flex-col gap-2", className)}>
      <div
        className="relative flex size-[148px] items-center justify-center"
        onKeyDown={onKeyDown}
      >
        <div role="menu" aria-label="Moment actions" className="absolute inset-0">
          {ITEMS.map((item, index) => {
            const radians = (item.angle * Math.PI) / 180;
            const x = Math.cos(radians) * RADIUS;
            const y = Math.sin(radians) * RADIUS;
            return (
              <motion.button
                key={item.label}
                ref={(node) => {
                  items.current[index] = node;
                }}
                type="button"
                role="menuitem"
                tabIndex={shown ? 0 : -1}
                aria-hidden={!shown}
                aria-label={item.label}
                onClick={() => {
                  setChosen(item.label);
                  close(true);
                }}
                animate={
                  reduce
                    ? {
                        x: shown ? x : 0,
                        y: shown ? y : 0,
                        scale: shown ? 1 : 0.4,
                        opacity: shown ? 1 : 0,
                      }
                    : {
                        x: shown ? x : 0,
                        y: shown ? y : 0,
                        scale: shown ? 1 : 0,
                        opacity: shown ? 1 : 0,
                      }
                }
                transition={
                  reduce
                    ? { duration: 0 }
                    : { ...springBounce, delay: shown ? index * 0.025 : 0 }
                }
                style={{ pointerEvents: shown ? "auto" : "none" }}
                className="absolute left-1/2 top-1/2 -ml-[17px] -mt-[17px] flex size-[34px] items-center justify-center rounded-full border border-white/12 bg-[#1c1c21] text-white/70 outline-none hover:bg-white hover:text-black focus-visible:ring-2 focus-visible:ring-white/60"
              >
                <item.Icon className="size-3.5" aria-hidden="true" />
              </motion.button>
            );
          })}
        </div>

        <button
          ref={trigger}
          type="button"
          aria-haspopup="menu"
          aria-expanded={shown}
          aria-label={shown ? "Close the radial menu" : "Open the radial menu"}
          onClick={() => setOpen((value) => !value)}
          className="relative z-10 flex size-[46px] items-center justify-center rounded-full bg-white text-black outline-none focus-visible:ring-2 focus-visible:ring-black/40"
        >
          <motion.span
            className="block h-[2px] w-4 rounded-full bg-black"
            animate={{ rotate: shown ? 45 : 0, y: shown ? 0 : -3 }}
            transition={reduce ? { duration: 0 } : springBounce}
          />
          <motion.span
            className="absolute block h-[2px] w-4 rounded-full bg-black"
            animate={{ rotate: shown ? -45 : 0, y: shown ? 0 : 3 }}
            transition={reduce ? { duration: 0 } : springBounce}
          />
        </button>
      </div>
      <span
        aria-live="polite"
        className="text-[12px] uppercase tracking-[0.18em] text-white/45"
      >
        {chosen ?? (shown ? "Choose" : "Actions")}
      </span>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}
